use std::thread;
use std::time::{Duration, Instant};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // A synchronous blocking sleep inside an async task BLOCKS the
    // entire worker thread: no other task scheduled on this worker
    // makes progress for 500ms. With 4 workers, 4 concurrent
    // blocking calls stall all cores — the runtime cannot preempt.
    let start = Instant::now();
    thread::sleep(Duration::from_millis(500));
    println!("blocked the worker for {:?}", start.elapsed());

    // The same applies to sync file/socket reads and mutexes held
    // across awaits — anything that parks the OS thread, not the
    // async task. See main.rs in the "good" version for the fix.
    Ok(())
}

use std::fs;
use tokio::task;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // spawn_blocking hands the synchronous work to a dedicated
    // blocking thread pool, so the async worker threads keep
    // polling tasks. The JoinHandle awaits the blocking result
    // without stalling the scheduler.
    let data = task::spawn_blocking(|| fs::read("big.bin")).await??;

    // The same rule applies to any CPU-heavy synchronous work:
    // use spawn_blocking for blocking I/O and CPU crunch, or
    // better, use the async versions (tokio::fs::read) which
    // delegate to the blocking pool internally.
    let data2 = tokio::fs::read("big.bin").await?;

    assert_eq!(data.len(), data2.len());
    Ok(())
}
